(() => {
'use strict';
const root=document.getElementById('portal-app');
if(!root)return;
const day=86400000,now=Date.now();
const date=(days,hour=20)=>{const d=new Date(Date.now()+days*day);d.setUTCHours(hour,0,0,0);return d.toISOString();};
const empty=()=>({students:[],parents:[],lessons:[],threads:[],reports:[],invoices:[],payments:[],categories:[],resources:[],onboardings:[],notifications:[],settings:{},calendarView:'Week',calendarOffset:0,entitled:false});
let db=empty(),me=null,account='',activeChild='',busy=false,socket=null,refreshPending=false;
const qs=()=>new URLSearchParams(location.search);
const path=()=>location.pathname.replace(/\/?$/,'/');
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const role=()=>me?.role||'';
const currentStudent=()=>db.students.find(s=>s.id===(role()==='student'?me.studentId:activeChild))||db.students[0];
const personName=()=>me?.name||'';
const zone=()=>role()==='student'?currentStudent()?.zone||'America/Toronto':role()==='parent'?db.parents.find(p=>p.id===me.parentId)?.zone||'America/Toronto':'America/Toronto';
const fmt=(value,options={})=>{const d=new Date(value);let z=zone();const m=z.match(/^GMT\s*([+-])\s*(\d{1,2})(?::(\d{2}))?$/i);if(m){d.setUTCMinutes(d.getUTCMinutes()+(m[1]==='-'?-1:1)*(Number(m[2])*60+Number(m[3]||0)));z='UTC';}try{return new Intl.DateTimeFormat('en-CA',{timeZone:z,...options}).format(d);}catch{return new Intl.DateTimeFormat('en-CA',{timeZone:'UTC',...options}).format(d);}};
const shortDate=x=>fmt(x,{month:'short',day:'numeric'});
const fullDate=x=>fmt(x,{weekday:'long',month:'long',day:'numeric',year:'numeric'});
const time=x=>fmt(x,{hour:'numeric',minute:'2-digit',timeZoneName:'short'});
const timestamp=x=>fmt(x,{month:'short',day:'numeric',hour:'numeric',minute:'2-digit',timeZoneName:'short'});
const money=(x,c='USD')=>new Intl.NumberFormat('en-CA',{style:'currency',currency:c,currencyDisplay:'code'}).format(x);
const student=id=>db.students.find(s=>s.id===id);
const canStudent=id=>role()==='admin'||(role()==='student'&&id===me.studentId)||(role()==='parent'&&student(id)?.parentId===me.parentId);
const visibleStudents=()=>db.students.filter(s=>canStudent(s.id));
const upcoming=id=>db.lessons.filter(l=>l.studentId===id&&l.status==='Scheduled'&&new Date(l.start)>new Date()).sort((a,b)=>new Date(a.start)-new Date(b.start));
const visibleInvoices=()=>db.invoices.filter(i=>role()==='admin'||(role()==='parent'&&canStudent(i.studentId)&&i.issued));
const invoiceTotal=i=>Number.isFinite(i.totalOverride)?i.totalOverride:Math.round(i.count*(i.hoursPerLesson||1)*i.rate*(1-i.discount/100)*100)/100;
const invoiceBalance=i=>i.status==='Paid'?0:Math.max(0,invoiceTotal(i)-i.received);
const balanceValue=(s,k)=>s.balanceVerified===false?'To review':k==='remaining'?s.purchased-s.used:s[k];
const lessonTime=l=>l.timeVerified===false?'Time not recorded':time(l.start);
const lessonHours=l=>l.durationVerified===false?'Duration not recorded':`${l.hours} hour`;
const cancellationLabel=l=>l.chargeable===null?'Charge status to review':l.chargeable?'Chargeable':l.rescheduleRequired?'Rescheduling applies':'No charge';
const relativePrep=(at,start)=>{const h=(new Date(start)-new Date(at))/3600000;return h>=24?`${Math.floor(h/24)} day${Math.floor(h/24)===1?'':'s'} before the lesson`:h>=1?`${Math.floor(h)} hour${Math.floor(h)===1?'':'s'} before the lesson`:h>=0?`${Math.floor(h*60)} minutes before the lesson`:'after the lesson';};
const countdown=x=>{const min=Math.max(0,Math.floor((new Date(x)-new Date())/60000));const d=Math.floor(min/1440),h=Math.floor(min%1440/60);return d?`Your next lesson is in ${d} day${d===1?'':'s'}${h?`, ${h} hour${h===1?'':'s'}`:''}.`:h?`Your next lesson is in ${h} hour${h===1?'':'s'}, ${min%60} minutes.`:`Your next lesson is in ${min} minutes.`;};
const tag=(text,cls='')=>`<span class="tag ${esc(cls||text.toLowerCase().replace(/\s/g,'-'))}">${esc(text)}</span>`;
const button=(text,href,cls='')=>`<a class="button ${cls}" href="${href}">${esc(text)}</a>`;
const icon=n=>{const paths={home:'M3 10 12 3l9 7v10h-6v-6H9v6H3z',calendar:'M4 5h16v16H4z M7 3v4 M17 3v4 M4 10h16',book:'M3 4h7l2 2 2-2h7v15h-7l-2 2-2-2H3z M12 6v15',message:'M3 4h18v13H8l-5 4z',user:'M16 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0 M4 21v-3a8 8 0 0 1 16 0v3',bill:'M5 3h14v18l-3-2-4 2-4-2-3 2z M8 8h8 M8 12h8 M8 16h5',report:'M5 3h10l4 4v14H5z M14 3v5h5 M8 12h8 M8 16h6',grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',logout:'M10 4H4v16h6 M9 12h12 M17 8l4 4-4 4'};return `<svg class="portal-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linejoin="round" stroke-linecap="round" aria-hidden="true"><path d="${paths[n]||paths.book}"/></svg>`;};
const previewParams=()=>({role:qs().get('view'),student:qs().get('previewStudent')});
const href=(route,param='')=>{const q=new URLSearchParams(param),v=previewParams();if(v.role&&!q.has('view')){q.set('view',v.role);q.set('previewStudent',v.student||'');}return `/portal/${route}/${q.size?'?'+q:''}`;};
const controls=()=>db.preview?`<div class="review-banner" role="status"><div><strong>${esc(db.preview.role==='student'?'Student preview':'Parent preview')} · ${esc(db.preview.studentName)}</strong><p>Read-only preview for Amanda. Changes are not saved and no messages are sent.</p></div><div class="button-row"><button class="button secondary small-button" data-action="preview-onboarding">Preview onboarding</button><button class="button secondary small-button" data-action="exit-preview">Return to Amanda’s workspace</button></div></div>`:role()==='admin'&&db.settings.reviewMode?`<div class="review-banner" role="status"><div><strong>Private review · Family access is disabled</strong><p>Open a student record to preview the student or parent view. Imported details marked for review need checking.</p></div>${button('Review students',href('students'),'secondary small-button')}</div>`:'';
const header=()=>`<header class="portal-header"><a class="brand" href="/" aria-label="Auxesis Education home"><img src="/assets/logo.png" width="938" height="315" alt="Auxesis Education"></a><nav aria-label="Website navigation"><a href="/">Website</a><a class="library-link" href="/resources/">Resource Library</a>${role()?`<span class="identity"><span class="avatar teal">${esc(personName()[0])}</span><span class="name">${esc(personName())}</span></span><a href="/portal/" data-action="logout">Sign out</a>`:''}</nav></header>`;
const nav=()=>{let items=[['dashboard','Dashboard','home'],['lessons','Lessons','book'],['messages','Messages','message'],['account','Account','user']];if(role()==='parent')items=[['dashboard','Child dashboard','home'],['lessons','Lessons','book'],['reports','Monthly reports','report'],['messages','Messages','message'],['billing','Billing & invoices','bill'],['account','Account','user']];if(role()==='admin')items=[['dashboard','Overview','home'],['calendar','Calendar','calendar'],['students','Students','user'],['messages','Messages','message'],['billing','Billing & invoices','bill'],['account','Payment details','user']];return `<aside class="portal-sidebar"><p class="side-label">${role()==='admin'?'Amanda’s workspace':role()==='parent'?'Parent / guardian':'Student portal'}</p>${role()==='parent'?`<div class="child-picker"><label for="child">Viewing</label><select id="child">${visibleStudents().map(s=>`<option value="${s.id}" ${s.id===activeChild?'selected':''}>${esc(s.name)}</option>`).join('')}</select></div>`:''}<nav aria-label="Portal navigation">${items.map(([r,n,i])=>`<a href="${href(r)}" class="${path()===href(r)||(r==='lessons'&&path()===href('lesson'))||(r==='students'&&path()===href('student'))||(r==='billing'&&path()===href('invoice'))?'active':''}">${icon(i)}${n}</a>`).join('')}</nav><div class="side-resource"><nav><a href="/resources/">${icon('grid')}Resource Library</a>${role()==='admin'?`<a href="/resources/manage/">${icon('book')}Manage resources</a>`:''}</nav></div></aside>`;};
const shell=body=>`${controls()}${header()}<div class="portal-layout">${nav()}<main class="portal-main" id="main">${body}</main></div>${footer()}`;
const footer=()=>`<footer class="portal-footer"><span>© 2026 Auxesis Education</span><span><a href="/privacy-consent/">Privacy & consent</a></span></footer><div class="toast" role="status" aria-live="polite" hidden></div><dialog class="portal-dialog" id="action-dialog"></dialog>`;
const top=(title,subtitle='',action='')=>`<div class="page-top"><div><p class="portal-kicker">${role()==='admin'?'Amanda’s workspace':role()==='parent'?'Parent / guardian':'Student portal'}</p><h1>${esc(title)}</h1>${subtitle?`<p>${esc(subtitle)}</p>`:''}</div>${action}</div>`;
const field=(label,name,value='',type='text',extra='')=>`<label class="portal-field ${extra.includes('full')?'full':''}">${esc(label)}<input type="${type}" name="${esc(name)}" value="${esc(value)}" ${extra.replace('full','')}></label>`;
const area=(label,name,value='',hint='')=>`<label class="portal-field full">${esc(label)}<textarea name="${name}">${esc(value)}</textarea>${hint?`<span class="hint">${esc(hint)}</span>`:''}</label>`;
const select=(label,name,values,value)=>`<label class="portal-field">${esc(label)}<select name="${name}">${values.map(v=>`<option ${v===value?'selected':''}>${esc(v)}</option>`).join('')}</select></label>`;
const resourceSubjects=['Biology','Chemistry','ESS','Science','Practical skills','Research skills','Other'];
const resourceCurricula=['IB Diploma','IB MYP','GCSE / IGCSE','AS / A-Level','Ontario','Other'];
const resourceSelect=(label,name,values)=>`<label class="portal-field">${esc(label)}<select name="${name}" data-resource-select required><option value="" selected disabled>Select a ${label.toLowerCase()}</option>${values.map(v=>`<option value="${esc(v)}">${esc(v)}</option>`).join('')}</select></label>`;
const resourceOther=(label,name)=>`<label class="portal-field full" data-resource-other-for="${name}" hidden>${esc(label)} — please specify<input type="text" name="other_${name}" maxlength="300" disabled></label>`;
const resourceClassification=()=>resourceSelect('Subject','subject',resourceSubjects)+resourceOther('Subject','subject')+resourceSelect('Curriculum','programme',resourceCurricula)+resourceOther('Curriculum','programme');
function updateResourceOtherFields(form){form.querySelectorAll('[data-resource-other-for]').forEach(field=>{const show=form.elements.namedItem(field.dataset.resourceOtherFor).value==='Other',input=field.querySelector('input');field.hidden=!show;input.disabled=!show;input.required=show;});}
function resourceValues(values){const result={...values};for(const name of ['subject','programme']){if(result[name]==='Other')result[name]=(result['other_'+name]||'').trim();delete result['other_'+name];}return result;}

const filesHtml=files=>files?.length?`<div class="files">${files.map(f=>`<span class="file-chip"><a href="/api/portal/file?id=${encodeURIComponent(f.id)}" download="${esc(f.name)}">${esc(f.name)}</a></span>`).join('')}</div>`:'';
const lessonRow=l=>`<a class="lesson-row ${l.status==='Scheduled'&&upcoming(l.studentId)[0]?.id===l.id?'current':''}" href="${href('lesson','id='+l.id)}"><span class="date-tile"><small>${esc(fmt(l.start,{month:'short'}))}</small><strong>${esc(fmt(l.start,{day:'numeric'}))}</strong></span><span><span class="lesson-name">${role()==='admin'?esc(student(l.studentId).name)+' · ':''}${esc(l.subject)}</span><span class="meta">${esc(fmt(l.start,{weekday:'long'}))} · ${esc(lessonTime(l))} · ${esc(lessonHours(l))}</span></span><span class="row-right">${tag(l.status)}${l.status==='Scheduled'?tag(l.planning.length?'Planning added':'Planning needed',l.planning.length?'ready':'warning'):l.status==='Cancelled'?tag(cancellationLabel(l),l.chargeable?'warning':'ready'):''}</span></a>`;
const nextPanel=s=>{const l=upcoming(s.id)[0];return l?`<section class="panel next-lesson"><p class="portal-kicker">Next lesson</p><h2>${esc(l.subject)}</h2><span class="countdown" data-countdown="${l.start}">${esc(countdown(l.start))}</span><div class="lesson-date-line"><span>${esc(fullDate(l.start))}</span><span>${esc(time(l.start))}</span><span>${l.hours} hour</span></div>${tag(l.planning.length?'Planning added':'Planning needed',l.planning.length?'ready':'warning')}<p class="subtle" style="margin-top:1rem">${role()==='parent'?'See what '+esc(s.preferred)+' would like to work on.':role()==='admin'?'Open the shared record to review planning and prepare.':'Add questions, topics or materials before we meet.'}</p>${button('Open lesson record',href('lesson','id='+l.id))}</section>`:`<section class="panel"><h2>No upcoming lesson</h2><p>Message Amanda to discuss the next lesson.</p>${button('Message Amanda',href('messages'))}</section>`;};
const metric=(label,value,note='')=>`<div class="metric"><span class="label">${label}</span><span class="value">${value}</span>${note?`<span class="meta">${note}</span>`:''}</div>`;
function dashboard(){if(role()==='admin')return adminDashboard();const s=currentStudent(),l=upcoming(s.id)[0],last=db.lessons.filter(x=>x.studentId===s.id&&x.status==='Completed').sort((a,b)=>new Date(b.start)-new Date(a.start))[0];return top(role()==='parent'?s.preferred+'’s dashboard':'Hello, '+s.preferred,role()==='parent'?'Your child’s lessons, preparation and progress.':'Your lessons and the next steps in your learning.')+`<div class="portal-grid"><div class="stack">${nextPanel(s)}<section class="panel"><div class="panel-header"><h2>Recent lessons</h2><a class="plain-link" href="${href('lessons')}">All lessons</a></div><div class="lesson-list">${db.lessons.filter(x=>x.studentId===s.id&&new Date(x.start)<new Date()).sort((a,b)=>new Date(b.start)-new Date(a.start)).slice(0,2).map(lessonRow).join('')}</div></section></div><div class="stack"><section class="panel"><p class="portal-kicker">Continue from last time</p><h2>Your next steps</h2><p>${esc(last?.notes.next||'Your next steps will appear here after your lesson.')}</p>${last?`<a class="plain-link" href="${href('lesson','id='+last.id)}">See the completed lesson</a>`:''}</section><section class="panel"><h2>${role()==='parent'?'For you':'Need a hand?'}</h2>${role()==='parent'?`<div class="action-list"><a class="action-item" href="${href('billing')}">${icon('bill')}<span><strong>${balanceValue(s,'remaining')} ${s.balanceVerified===false?'· lesson balance':'lessons remaining'}</strong><span class="meta">View payments and issued invoices.</span></span></a><a class="action-item" href="${href('reports')}">${icon('report')}<span><strong>Monthly progress reports</strong><span class="meta">Private updates for parents and guardians.</span></span></a><a class="action-item" href="${href('messages')}">${icon('message')}<span><strong>Message Amanda</strong><span class="meta">Your own conversation with Amanda.</span></span></a></div>`:`<p>You can ask Amanda a question between lessons, or find a guide in the Resource Library.</p><div class="button-row">${button('Message Amanda',href('messages'),'secondary small-button')}${button('Browse resources','/resources/','secondary small-button')}</div>`}</section><section class="panel"><p class="portal-kicker">Your course</p><h2>${esc(s.programme+' '+s.subject)}</h2><p>${esc(s.year)} · ${esc(s.level)}</p><p class="meta">Examinations: ${esc(s.exam)}</p></section></div></div>`;}
function adminDashboard(){const todayLessons=db.lessons.filter(l=>fmt(l.start,{year:'numeric',month:'numeric',day:'numeric'})===fmt(new Date(),{year:'numeric',month:'numeric',day:'numeric'})),draft=db.invoices.filter(i=>!i.issued),unread=db.threads.filter(t=>t.unread),due=db.invoices.filter(i=>i.issued&&invoiceBalance(i)>0);return top('A clear view of your day',fullDate(new Date()),`<div class="button-row"><button class="button" data-action="schedule">Schedule lessons</button><button class="button secondary" data-action="invite-family">Invite family</button></div>`)+`<div class="metric-grid">${metric('Lessons today',todayLessons.length)}${metric('Messages to read',unread.length)}${metric('Draft invoices',draft.length)}</div><div class="portal-grid"><div class="stack"><section class="panel"><h2>Today’s lessons</h2>${todayLessons.map(lessonRow).join('')||'<p>No lessons scheduled today.</p>'}</section><section class="panel"><h2>Coming up</h2>${db.lessons.filter(l=>l.status==='Scheduled'&&new Date(l.start)>new Date()).sort((a,b)=>new Date(a.start)-new Date(b.start)).slice(0,5).map(lessonRow).join('')||'<p>Invite a family, then schedule their lessons.</p>'}</section></div><div class="stack"><section class="panel"><h2>Needs your attention</h2>${db.notifications.slice().reverse().slice(0,12).map(n=>`<p><a href="${n.lessonId?href('lesson','id='+n.lessonId):n.threadId?href('messages','thread='+n.threadId):href('students')}">${esc(n.text)}</a><br><span class="meta">${esc(timestamp(n.at))}</span></p>`).join('')||'<p>No updates yet.</p>'}</section><section class="panel"><h2>Financial reminders</h2>${due.map(i=>`<p><a href="${href('invoice','id='+i.id)}">${esc(student(i.studentId).name)} · ${money(invoiceBalance(i),i.currency)}</a> · ${esc(shortDate(i.due))}</p>`).join('')||'<p>No outstanding invoices.</p>'}${button('Review invoices',href('billing'),'secondary small-button')}</section></div></div>`;}
function lessonsPage(){const s=currentStudent();const ls=db.lessons.filter(l=>canStudent(l.studentId)&&(role()==='admin'||l.studentId===s.id));const future=ls.filter(l=>new Date(l.start)>new Date()).sort((a,b)=>new Date(a.start)-new Date(b.start)),past=ls.filter(l=>new Date(l.start)<=new Date()).sort((a,b)=>new Date(b.start)-new Date(a.start));return top(role()==='parent'?s.preferred+'’s lessons':'Lessons','Planning, completed records and resources in one place.')+`<div class="lesson-list">${future.map(lessonRow).join('')}${past.length?'<div class="list-divider">Earlier lessons</div>':''}${past.map(lessonRow).join('')}</div>`;}
function lessonPage(){const l=db.lessons.find(x=>x.id===qs().get('id'));if(!l||!canStudent(l.studentId))return unavailable();const s=student(l.studentId),isAdmin=role()==='admin',editable=role()!=='parent'&&l.status==='Scheduled';return `<a class="back-breadcrumb" href="${isAdmin?href('calendar'):href('lessons')}">Back to ${isAdmin?'calendar':'lessons'}</a><div class="record-hero"><div><p class="portal-kicker">${esc(s.name)} · Lesson record</p><h1>${esc(l.subject)}</h1><p>${esc(fullDate(l.start))} · ${esc(lessonTime(l))} · ${esc(lessonHours(l))}</p></div><div>${tag(l.status)}${l.status==='Cancelled'?tag(cancellationLabel(l),l.chargeable?'warning':'ready'):''}</div></div>${l.status==='Cancelled'?`<div class="notice ${l.chargeable?'warning':''}"><p>Cancelled ${l.cancelledAt?esc(timestamp(l.cancelledAt)):'· cancellation time not recorded'}${l.cancelledBy?' by '+esc(l.cancelledBy):''}${l.cancelledAt?' · '+relativePrep(l.cancelledAt,l.start):''}. ${l.chargeable===null?'The charging status needs Amanda’s review.':l.chargeable?'This lesson counts against the prepaid balance under the 12-hour rule.':l.rescheduleRequired?'Contact Amanda to reschedule within four weeks under the agreed policy.':'This lesson does not count against the prepaid balance.'}</p></div>`:''}<div class="portal-grid"><div class="stack"><section class="panel"><div class="panel-header"><h2>Planning for this lesson</h2>${tag(l.planning.length?'Planning added':'Not yet added',l.planning.length?'ready':'warning')}</div>${role()==='parent'?'<p class="meta">View-only · Planning is shared between the student and Amanda.</p>':''}${l.planning.length?l.planning.map(p=>`<article class="planning-item"><strong>${esc(p.author)}</strong><p>${esc(p.text)}</p><p class="meta">Added ${esc(timestamp(p.at))} · ${relativePrep(p.at,l.start)}</p>${filesHtml(p.files)}</article>`).join(''):'<p class="empty-note">No planning has been added yet.</p>'}${editable?`<form id="planning-form" data-lesson="${l.id}">${area('What would you like to work on?','planning','','Add topics, questions, assessment dates or areas you find difficult.')}<label class="portal-field" style="margin-top:1rem">Photos, screenshots or files<input class="attachment-input" type="file" name="files" multiple accept="image/*,.pdf,.docx,.txt,.pptx,.xlsx"></label><p class="meta" style="margin-top:.5rem">Maximum 2 MB per file · Up to three files at a time.</p><div class="button-row"><button class="button" type="submit">Add planning</button></div><p class="meta" style="margin-top:1rem">Aim to prepare 24–48 hours before the lesson. You can still add planning closer to the time.</p></form>`:''}</section><section class="panel"><div class="panel-header"><h2>After the lesson</h2>${l.status==='Completed'?tag('Completed','completed'):tag('Lesson notes','pending')}</div>${isAdmin?`<form id="notes-form" data-lesson="${l.id}"><details class="policy-details"><summary>Organise a conversational note</summary><p class="meta">Paste a brief note, review the suggested fields and save when ready.</p>${area('Lesson note','rawNotes','','Use “Covered:”, “Outcome:” and “Next steps:” when useful.')}<div class="button-row"><button type="button" class="button secondary small-button" data-action="organise-notes">Organise notes</button></div></details><div class="form-fields">${area('What We Covered','covered',l.notes.covered)}${area('Outcome','outcome',l.notes.outcome,'Strengths, difficulties, understanding, progress or skills as relevant.')} ${area('Next Steps','next',l.notes.next,'Include homework or practice here.')}</div><div class="button-row"><button class="button" type="submit">Save lesson notes</button>${l.status==='Scheduled'&&new Date(l.start)<new Date()?`<button class="button secondary" type="button" data-action="no-show" data-id="${l.id}">Record no-show</button>`:''}${l.status==='Scheduled'?`<button class="button secondary" type="button" data-action="complete-lesson" data-id="${l.id}">Mark completed</button>`:''}</div></form>`:l.notes.covered||l.notes.outcome||l.notes.next?['covered','outcome','next'].map((k,i)=>`<div class="notes-section"><h3>${['What We Covered','Outcome','Next Steps'][i]}</h3><p>${esc(l.notes[k]||'—')}</p></div>`).join(''):'<p class="empty-note">Your lesson notes will appear here after the lesson.</p>'}</section><section class="panel"><h2>Lesson resources</h2><p class="meta">Materials attached to this lesson.</p>${l.resources.map(id=>{const r=db.resources.find(x=>x.id===id);return r?`<p>${button(r.title,'/resources/resource/?id='+r.id,'secondary small-button')}</p>`:'';}).join('')||'<p class="empty-note">No resources attached yet.</p>'}${filesHtml(l.attachedFiles)}${isAdmin?`<form id="lesson-resource-form" data-lesson="${l.id}"><label class="portal-field">Attach from the Resource Library<select name="resource">${db.resources.map(r=>`<option value="${r.id}">${esc(r.programme+' · '+r.title)}</option>`).join('')}</select></label><div class="button-row"><button class="button secondary small-button">Attach resource</button></div></form>`:''}</section></div><div class="stack"><section class="panel"><h2>Lesson details</h2><dl class="detail-list"><dt>Student</dt><dd>${esc(s.name)}</dd><dt>Programme</dt><dd>${esc(s.programme)}</dd><dt>Course</dt><dd>${esc(s.subject+' · '+s.level)}</dd><dt>Duration</dt><dd>${l.durationVerified===false?'Not recorded':l.hours*60+' minutes'}</dd></dl><div class="button-row">${button(isAdmin?'Message student':'Message Amanda',href('messages','thread='+s.id+'-student'),'secondary small-button')}${isAdmin?button('Message parent',href('messages','thread='+s.parentId+'-parent'),'secondary small-button'):''}</div>${role()==='parent'?'<p class="meta" style="margin-top:.8rem">Student messages open in view-only mode.</p>':''}</section>${role()==='parent'&&l.status==='Scheduled'&&new Date(l.start)>new Date()?`<section class="panel"><h2>Change of plans?</h2><p>You can cancel this lesson here. To discuss moving it, message Amanda.</p><p class="meta">Less than 12 hours’ notice is chargeable. The cancelled lesson stays in the record.</p><div class="button-row"><button class="button danger" data-action="cancel-lesson" data-id="${l.id}">Cancel lesson</button>${button('Message Amanda',href('messages','thread='+me.parentId+'-parent'),'secondary small-button')}</div></section>`:''}${isAdmin?`<section class="panel"><h2>Schedule</h2><div class="button-row"><button class="button secondary" data-action="reschedule" data-id="${l.id}">Move lesson</button>${l.status==='Scheduled'?`<button class="button danger" data-action="tutor-cancel" data-id="${l.id}">Tutor cancellation</button>`:''}</div></section><section class="panel"><h2>Private notes</h2><p class="meta">Visible only to Amanda.</p><form id="private-notes-form" data-lesson="${l.id}">${area('Private note','private',l.privateNotes)}<div class="button-row"><button class="button secondary small-button">Save private note</button></div></form></section><section class="panel"><h2>Student record</h2><p>${esc(s.name)}<br><span class="meta">${esc(db.parents.find(p=>p.id===s.parentId)?.name||'Not recorded')} · Parent</span></p>${button('Open student profile',href('student','id='+s.id),'secondary small-button')}</section>`:''}</div></div>`;}
function messagesPage(){const s=currentStudent();let ts=db.threads.filter(t=>role()==='admin'||(role()==='student'&&t.kind==='student'&&t.studentId===me.studentId)||(role()==='parent'&&(t.parentId===me.parentId||t.studentId&&canStudent(t.studentId))));const selected=ts.find(t=>t.id===qs().get('thread'))||ts.find(t=>role()==='parent'?t.kind==='parent':true)||ts[0];if(!selected)return top('Messages')+'<p class="empty-note">No conversations yet.</p>';const readonly=role()==='parent'&&selected.kind==='student';const myName=personName();return top('Messages',role()==='admin'?'Student and parent conversations.':readonly?'Your child’s conversation with Amanda · View-only':'Your conversation with Amanda.')+`<div class="message-layout"><nav class="thread-list" aria-label="Message conversations">${ts.map(t=>`<a href="${href('messages','thread='+t.id)}" class="${t.id===selected.id?'active':''}"><strong>${esc(role()==='admin'?t.name:t.kind==='parent'?'Parent ↔ Amanda':role()==='student'?'Amanda':t.name+' ↔ Amanda')}</strong><span class="meta">${t.kind==='parent'?'Parent conversation':'Student conversation'} ${role()==='admin'&&t.unread?'· Unread':''}</span></a>`).join('')}</nav><section class="thread-view"><div class="thread-title"><h2>${esc(role()==='admin'?selected.name:readonly?selected.name+' ↔ Amanda':'Amanda')}</h2>${tag(selected.kind==='parent'?'Parent thread':'Student thread',selected.kind==='parent'?'parent':'')}${role()==='admin'?`<button class="button secondary small-button" data-action="mark-read" data-id="${selected.id}">${selected.unread?'Mark read':'Read'}</button>`:''}</div><div class="message-history">${selected.messages.map(m=>`<article class="message-bubble ${m.author===myName?'mine':''}"><p>${esc(m.text)}</p>${filesHtml(m.files)}<span class="meta">${esc(m.author)} · ${esc(timestamp(m.at))}</span></article>`).join('')}</div>${readonly?'<div class="message-composer"><p class="meta">This is the student’s thread. Use your parent conversation to message Amanda.</p></div>':`<form class="message-composer" id="message-form" data-thread="${selected.id}">${area('Message','message','','')}<div class="button-row"><label class="portal-field"><span class="screen-reader">Attach photos or files</span><input class="attachment-input" name="files" type="file" multiple accept="image/*,.pdf,.txt,.docx"></label><button class="button" type="submit">Send message</button></div><p class="meta" style="margin:.7rem 0 0">Messages and attachments are saved in your private conversation.</p></form>`}</section></div>`;}
function reportsPage(){if(role()!=='parent'&&role()!=='admin')return unavailable();const s=currentStudent(),rs=db.reports.filter(r=>r.studentId===s.id&&(role()==='admin'||r.status==='Published'));return top(s.preferred+'’s monthly reports','Private progress updates for parents and guardians.')+`<div class="stack">${rs.length?rs.map(r=>`<section class="panel"><div class="panel-header"><h2>${esc(r.month)}</h2>${tag(r.status,r.status==='Published'?'ready':'draft')}</div><p class="meta">${r.publishedAt?'Published '+esc(shortDate(r.publishedAt)):'Draft · Amanda only'}</p><div class="report-content">${esc(r.body)}</div></section>`).join(''):'<section class="panel"><h2>No reports published yet</h2><p>Amanda’s monthly update will appear here when it is ready.</p></section>'}<div class="notice"><p>Reports are visible to parents and guardians. You can share an update with your child outside the portal if you choose.</p></div></div>`;}
function billingPage(){if(role()==='student')return unavailable();if(role()==='admin')return adminBilling();const s=currentStudent(),invs=visibleInvoices().filter(i=>i.studentId===s.id),payments=db.payments.filter(p=>p.studentId===s.id).sort((a,b)=>new Date(b.date)-new Date(a.date)),last=payments[0],next=upcoming(s.id)[0],due=invs.filter(i=>invoiceBalance(i)>0).sort((a,b)=>new Date(a.due)-new Date(b.due))[0];return top('Billing & invoices',s.name+' · '+s.currency)+`<div class="metric-grid">${metric('Opening prepaid lessons',balanceValue(s,'purchased'))}${metric('Used since import',balanceValue(s,'used'))}${metric('Lessons remaining',balanceValue(s,'remaining'))}</div><div class="portal-grid equal"><section class="panel"><h2>Billing summary</h2><dl class="detail-list"><dt>Last payment</dt><dd>${last?money(last.amount,last.currency):'—'}</dd><dt>Received</dt><dd>${last?shortDate(last.date):'—'}</dd><dt>Payment method</dt><dd>${last?esc(last.method):'—'}</dd><dt>Next lesson</dt><dd>${next?esc(shortDate(next.start)+' · '+time(next.start)):'Not scheduled'}</dd><dt>Next payment due</dt><dd>${due?esc(shortDate(due.due)):s.balanceVerified===false?'To review':'No payment due'}</dd><dt>Balance / credit</dt><dd>${due?money(invoiceBalance(due),due.currency):s.balanceVerified===false?'To review':money(0,s.currency)}</dd></dl></section><section class="panel"><h2>How to pay</h2><p>Payment is made outside the portal, then Amanda records it against your invoice.</p><p>Canadian e-Transfer · Bank transfer · PayPal</p>${paymentOptions()}</section></div><section style="margin-top:1.8rem"><h2>Issued invoices</h2>${invoiceTable(invs)}</section><section style="margin-top:1.8rem"><h2>Payment history</h2><div class="table-wrap"><table class="portal-table"><thead><tr><th>Received</th><th>Method</th><th>Lessons</th><th>Amount</th></tr></thead><tbody>${payments.map(p=>`<tr><td>${shortDate(p.date)}</td><td>${esc(p.method)}</td><td>${p.historical?'Imported history':p.lessons}</td><td class="money">${money(p.amount,p.currency)}</td></tr>`).join('')}</tbody></table></div></section>`;}
function invoiceTable(items){return `<div class="table-wrap"><table class="portal-table"><thead><tr><th>Invoice</th>${role()==='admin'?'<th>Student</th>':''}<th>Due date</th><th>Status</th><th>Amount</th><th>Balance</th></tr></thead><tbody>${items.map(i=>`<tr><td><a class="plain-link" href="${href('invoice','id='+i.id)}">${esc(i.number)}</a></td>${role()==='admin'?`<td>${esc(student(i.studentId).name)}</td>`:''}<td>${shortDate(i.due)}</td><td>${tag(i.status)}</td><td class="money">${money(invoiceTotal(i),i.currency)}</td><td class="money">${money(invoiceBalance(i),i.currency)}</td></tr>`).join('')||`<tr><td colspan="6">No invoices in this view.</td></tr>`}</tbody></table></div>`;}
function adminBilling(){const filter=qs().get('filter')||'all',items=visibleInvoices().filter(i=>filter==='all'||filter==='draft'&&!i.issued||filter==='due'&&i.issued&&invoiceBalance(i)>0||filter==='paid'&&i.status==='Paid');return top('Billing & invoicing','Review drafts, record payments and track lesson balances.',`<button class="button" data-action="prepare-invoice">Prepare invoice</button>`)+`<div class="profile-tabs"><a class="${filter==='all'?'active':''}" href="${href('billing')}">All invoices</a><a class="${filter==='draft'?'active':''}" href="${href('billing','filter=draft')}">Draft / future</a><a class="${filter==='due'?'active':''}" href="${href('billing','filter=due')}">Payments due</a><a class="${filter==='paid'?'active':''}" href="${href('billing','filter=paid')}">Paid</a></div>${invoiceTable(items)}${sourceHistoryPanel()}${sourceArchivePanel()}<section style="margin-top:2rem"><h2>Lesson balances</h2><div class="table-wrap"><table class="portal-table"><thead><tr><th>Student</th><th>Purchased</th><th>Used</th><th>Remaining</th><th>Currency</th></tr></thead><tbody>${db.students.map(s=>`<tr><td><a class="plain-link" href="${href('student','id='+s.id+'&tab=billing')}">${esc(s.name)}</a></td><td>${balanceValue(s,'purchased')}</td><td>${balanceValue(s,'used')}</td><td>${balanceValue(s,'remaining')}</td><td>${s.currency}</td></tr>`).join('')}</tbody></table></div></section>`;}
function invoicePage(){const i=visibleInvoices().find(x=>x.id===qs().get('id'));if(!i||role()==='student')return unavailable();const s={...student(i.studentId),rate:i.rate,discount:i.discount,currency:i.currency},p=db.parents.find(p=>p.id===s.parentId);return `<a class="back-breadcrumb" href="${href('billing')}">Back to billing</a>${top('Invoice '+i.number,i.issued?'Issued invoice':'Draft · Visible only to Amanda')}${i.importReview?'<div class="notice warning"><p>Imported invoice · retained for review. Issuing and payment changes are paused until reconciliation.</p></div>':''}<div class="invoice-paper" id="invoice-paper"><div class="invoice-heading"><img src="/assets/logo.png" alt="Auxesis Education"><div><h1>Invoice</h1><p>${esc(i.number)}</p>${tag(i.status)}</div></div><div class="invoice-info"><div><p class="portal-kicker">Bill to</p><p><strong>${esc(p.billingName)}</strong></p><p>Student: ${esc(s.name)}</p><p>${esc(p.email||'Not recorded')}</p></div><div><p>Invoice date: ${shortDate(i.date)}</p><p><strong>Due: ${shortDate(i.due)}</strong></p><p>Rate: ${money(s.rate,s.currency)} / hour</p><p>Discount: ${s.discount}%</p><p>Currency: ${s.currency}</p></div></div><div class="table-wrap"><table class="portal-table"><thead><tr><th>Date</th><th>Description</th><th>Hours</th><th>Amount</th></tr></thead><tbody>${i.dates.length?i.dates.map(d=>`<tr><td>${shortDate(d)}</td><td>${esc(s.programme+' '+s.subject+' tutoring')}</td><td>${i.hoursPerLesson||1}</td><td class="money">${money(s.rate*(i.hoursPerLesson||1),s.currency)}</td></tr>`).join(''):'<tr><td colspan="4">Lesson dates to be confirmed · '+i.count+' lessons</td></tr>'}</tbody></table></div><div class="invoice-totals"><span>Subtotal</span><span>${money(i.count*(i.hoursPerLesson||1)*s.rate,s.currency)}</span><span>Discount (${s.discount}%)</span><span>−${money(i.count*(i.hoursPerLesson||1)*s.rate*s.discount/100,s.currency)}</span>${i.appliedCredit?`<span>Applied credit</span><span>−${money(i.appliedCredit,s.currency)}</span>`:''}<strong>Total</strong><strong>${money(invoiceTotal(i),s.currency)}</strong><span>Payment received</span><span>${money(i.received,s.currency)}</span><strong>Balance due</strong><strong>${money(invoiceBalance(i),s.currency)}</strong>${i.credit?`<span>Credit</span><span>${money(i.credit,s.currency)}</span>`:''}</div><div class="invoice-pay"><h3>Payment reference</h3><p>${esc(s.name+' · '+i.number)}</p><p>PayPal · Bank transfer · Canadian e-Transfer</p><p class="meta">Amanda records payments against this invoice after they are received.</p>${paymentOptions()}</div></div><div class="button-row" style="max-width:900px;margin:1.2rem auto"><button class="button secondary" data-action="download-invoice" data-id="${i.id}">Download PDF</button><button class="button secondary" data-action="print">Print</button>${role()==='admin'&&!i.issued&&!i.importReview?`<button class="button" data-action="issue-invoice" data-id="${i.id}">Issue invoice</button>`:''}${role()==='admin'&&i.issued&&invoiceBalance(i)>0&&!i.importReview?`<button class="button" data-action="record-payment" data-id="${i.id}">Record payment</button>`:''}</div>`;}
function calendarPage(){if(role()!=='admin')return unavailable();const mode=db.calendarView,base=new Date(now+db.calendarOffset*(mode==='Month'?30:mode==='Week'?7:1)*day);let body='';if(mode==='Month'){const first=new Date(base.getUTCFullYear(),base.getUTCMonth(),1),start=new Date(first);start.setDate(start.getDate()-((start.getDay()+6)%7));body=`<div class="calendar-scroll"><div class="calendar-grid">${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map(d=>`<div class="day-head">${d}</div>`).join('')}${Array.from({length:42},(_,n)=>{const d=new Date(start.getTime()+n*day),ls=db.lessons.filter(l=>new Date(l.start).toDateString()===d.toDateString());return `<div class="calendar-cell ${d.getMonth()!==base.getMonth()?'muted':''} ${d.toDateString()===new Date().toDateString()?'today':''}"><strong>${d.getDate()}</strong>${ls.map(l=>`<a href="${href('lesson','id='+l.id)}" class="${l.status==='Cancelled'?'cancelled':''}">${time(l.start)}<br>${esc(student(l.studentId).preferred)}<br>${esc(l.subject)}</a>`).join('')}</div>`;}).join('')}</div></div>`;}else{const start=new Date(base);if(mode==='Week')start.setDate(start.getDate()-((start.getDay()+6)%7));start.setHours(0,0,0,0);const days=mode==='Week'?7:1;body=Array.from({length:days},(_,n)=>{const d=new Date(start.getTime()+n*day),ls=db.lessons.filter(l=>new Date(l.start).toDateString()===d.toDateString()).sort((a,b)=>new Date(a.start)-new Date(b.start));return `<section style="margin-bottom:1.5rem"><div class="list-divider">${esc(fullDate(d))}${d.toDateString()===new Date().toDateString()?' · Today':''}</div><div class="lesson-list">${ls.length?ls.map(lessonRow).join(''):'<p class="meta" style="margin:.5rem 0">No lessons scheduled.</p>'}</div></section>`;}).join('');}return top('Calendar','Your lessons, shared records and planning.',`<button class="button" data-action="schedule">Schedule lessons</button>`)+`<div class="calendar-controls"><div class="button-row" style="margin:0"><button class="button secondary small-button" data-action="calendar-prev">Previous</button><button class="button secondary small-button" data-action="calendar-today">Today</button><button class="button secondary small-button" data-action="calendar-next">Next</button></div><h2 style="margin:0">${esc(fmt(base,{month:'long',year:'numeric'}))}</h2><div class="segmented" role="group" aria-label="Calendar view">${['Today','Week','Month'].map(v=>`<button class="${mode===v?'active':''}" data-action="calendar-view" data-view="${v}">${v}</button>`).join('')}</div></div>${body}`;}
function studentsPage(){if(role()!=='admin')return unavailable();const query=(qs().get('q')||'').toLowerCase();return top('Students','Each student’s lessons, messages, billing and reports in one record.',`<button class="button" data-action="invite-family">Invite family</button>`)+`<form id="student-search" class="search-row"><input class="search-input" type="search" name="q" value="${esc(qs().get('q')||'')}" placeholder="Search students" aria-label="Search students"><button class="button secondary">Search</button></form><div class="student-cards">${db.students.filter(s=>s.name.toLowerCase().includes(query)).map(s=>`<a class="student-card" href="${href('student','id='+s.id)}"><span class="avatar teal">${esc(s.preferred[0])}</span><h2>${esc(s.name)}</h2><p>${esc(s.programme+' '+s.subject+' · '+s.level)}</p><p class="meta">${esc(s.year)}</p><p>${balanceValue(s,'remaining')} ${s.balanceVerified===false?'· lesson balance':'lessons remaining'}</p><p class="meta">Parent: ${esc(db.parents.find(p=>p.id===s.parentId)?.name||'Not recorded')}</p></a>`).join('')||'<p>No students match your search.</p>'}</div>`;}
function sourceArchivePanel(){const rows=db.billingArchive||[];return rows.length?`<details class="panel" style="margin-top:1.5rem"><summary>Historical invoice register · ${rows.length} source entries</summary><p class="meta">These source entries remain separate from current invoices and opening balances.</p><div class="table-wrap"><table class="portal-table"><thead><tr><th>Reference</th><th>Student</th><th>Period</th><th>Amount</th><th>Currency</th><th>Status / evidence</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.sourceData['Invoice ID'])}</td><td>${esc(r.studentName)}</td><td>${esc(r.sourceData['Service period'])}</td><td>${esc(r.sourceData['Gross amount'])}</td><td>${esc(r.sourceData.Currency)}</td><td>${esc(r.sourceData.Status)}<br>${esc(r.sourceData['Evidence note'])}</td></tr>`).join('')}</tbody></table></div></details>`:'';}
function sourceHistoryPanel(s){const rows=(db.billingHistory||[]).filter(r=>!s||r.studentId===s.id);return rows.length?`<section class="panel" style="margin-top:1.5rem"><h2>Original billing records</h2><p class="meta">Imported source entries are retained for reconciliation. They do not add prepaid lessons or create new payment demands.</p><div class="table-wrap"><table class="portal-table"><thead><tr><th>Student / reference</th><th>Status</th><th>Billed</th><th>Received</th><th>Currency</th><th>Source note</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(student(r.studentId)?.name||'')}<br>${esc(r.sourceData['Invoice #']||'Reference not recorded')}</td><td>${esc(r.sourceData.Status||'Not recorded')}</td><td>${esc(r.sourceData['Amount Billed']||'Not recorded')}</td><td>${esc(r.sourceData['Amount Received']||'Not recorded')}</td><td>${esc(r.sourceData.Currency||'Not recorded')}</td><td>${esc(r.sourceData.Notes||'')}</td></tr>`).join('')}</tbody></table></div></section>`:'';}
function importReviewPanel(s){if(role()!=='admin'||!s.migration)return '';return `<section class="panel import-review"><h2>Imported record · review before family access</h2><p>Family sign-in is disabled. Contact details and policy acknowledgements have not been invented.</p>${s.reviewFlags?.length?`<ul>${s.reviewFlags.map(t=>`<li>${esc(t)}</li>`).join('')}</ul>`:''}${button('Open original tracker',s.migration.sourceUrl,'secondary small-button')}</section>`;}
function studentPage(){if(role()!=='admin')return unavailable();const s=student(qs().get('id'));if(!s)return unavailable();const tab=qs().get('tab')||'overview',p=db.parents.find(p=>p.id===s.parentId);let body='';if(tab==='overview')body=`<div class="portal-grid equal"><section class="panel"><h2>Student information</h2><dl class="detail-list"><dt>Name</dt><dd>${esc(s.name)}</dd><dt>Preferred name</dt><dd>${esc(s.preferred)}</dd><dt>Pronouns</dt><dd>${esc(s.pronouns||'Not provided')}</dd><dt>Email</dt><dd>${esc(s.email||'Not recorded')}</dd><dt>Country</dt><dd>${esc(s.country)}</dd><dt>Time zone</dt><dd>${esc(s.zone)}</dd><dt>Year / level</dt><dd>${esc(s.year)}</dd><dt>Programme</dt><dd>${esc(s.programme)}</dd><dt>Course</dt><dd>${esc(s.subject+' · '+s.level)}</dd><dt>Exam board</dt><dd>${esc(s.board)}</dd><dt>Examinations</dt><dd>${esc(s.exam)}</dd></dl></section><section class="panel"><h2>Parent / guardian</h2><dl class="detail-list"><dt>Name</dt><dd>${esc(p.name||'Not recorded')}</dd><dt>Email</dt><dd>${esc(p.email||'Not recorded')}</dd><dt>Mobile</dt><dd>${esc(p.mobile)}</dd><dt>Time zone</dt><dd>${esc(p.zone)}</dd><dt>Preferred contact</dt><dd>${esc(p.contact)}</dd></dl><div class="button-row">${button('Message parent',href('messages','thread='+p.id+'-parent'),'secondary small-button')}${button('Message student',href('messages','thread='+s.id+'-student'),'secondary small-button')}</div></section><section class="panel"><h2>Onboarding</h2>${(()=>{const o=db.onboardings.find(o=>o.studentId===s.id);return `<p>${o?.complete?'Complete':'In progress'}${o?` · Step ${Math.min(o.step+1,5)} of 5`:''}</p>${(o?.agreements||[]).map(a=>`<p class="meta">${esc(a.policy)} · ${esc(a.who)} · ${esc(timestamp(a.at))} · Version ${esc(a.version)}</p>`).join('')}`;})()}</section><section class="panel"><h2>Learning priorities</h2><h3>What the student hopes to achieve</h3><p>${esc(s.goals)}</p><h3>Current challenges</h3><p>${esc(s.challenge)}</p></section><section class="panel"><h2>Files & resources</h2><div class="files">${[...new Set(db.lessons.filter(l=>l.studentId===s.id).flatMap(l=>l.resources))].map(id=>{const r=db.resources.find(r=>r.id===id);return r?button(r.title,'/resources/resource/?id='+id,'secondary small-button'):'';}).join('')||'<p>No resources attached yet.</p>'}</div></section></div>`;
if(tab==='arrangements')body=`<section class="panel"><h2>Tutoring arrangements</h2><p class="meta">Only Amanda can change these arrangements.</p><form id="arrangements-form" data-student="${s.id}"><div class="form-fields">${field('Regular day','day',s.day)}${field('Regular time','time',s.time)}${field('Lesson length (minutes)','length',s.length,'number','min="15" max="180" required')}${field('Frequency','frequency',s.frequency)}${field('Hourly rate','rate',s.rate,'number','min="1" step="0.01" required')}${select('Currency','currency',['USD','CAD','GBP','EUR','AUD'],s.currency)}${field('Discount (%)','discount',s.discount,'number','min="0" max="100" required')}${field('Start date','startDate',s.startDate?.slice(0,10)||'','date')}${field('Tutoring end date (optional)','endDate',s.endDate?.slice(0,10)||'','date')}${field('Purchased lesson balance','purchased',s.purchased,'number','min="0" step="0.5"')}</div><div class="notice"><p>Ending tutoring keeps full Resource Library access for one additional calendar month. Changes update the agreed arrangement; use the calendar to schedule or move individual lessons.</p></div><div class="button-row"><button class="button">Save arrangements</button></div></form></section>`;
if(tab==='lessons')body=`<div class="lesson-list">${db.lessons.filter(l=>l.studentId===s.id).sort((a,b)=>new Date(b.start)-new Date(a.start)).map(lessonRow).join('')}</div>`;
if(tab==='messages')body=`<div class="portal-grid equal">${db.threads.filter(t=>t.studentId===s.id||t.parentId===s.parentId).map(t=>`<section class="panel"><h2>${t.kind==='parent'?'Parent':'Student'} messages</h2><p>${esc(t.name)}</p>${button('Open conversation',href('messages','thread='+t.id),'secondary')}</section>`).join('')}</div>`;
if(tab==='billing')body=`<div class="metric-grid">${metric('Opening prepaid lessons',balanceValue(s,'purchased'))}${metric('Used since import',balanceValue(s,'used'))}${metric('Remaining',balanceValue(s,'remaining'))}</div>${invoiceTable(db.invoices.filter(i=>i.studentId===s.id))}${sourceHistoryPanel(s)}`;
if(tab==='reports'){const rs=db.reports.filter(r=>r.studentId===s.id);body=`<section class="panel"><div class="panel-header"><h2>Monthly parent report</h2>${tag('Parent-only','parent')}</div><p>Use lesson records as a starting point, then review the update before publishing.</p><form id="report-form" data-student="${s.id}">${field('Report month','month',fmt(new Date(),{month:'long',year:'numeric'}))}${area('Progress update','body','','Learning, strengths, areas for development, preparation and priorities.')}<div class="button-row"><button type="button" class="button secondary" data-action="draft-report" data-student="${s.id}">Draft from lesson records</button><button type="submit" class="button secondary" name="mode" value="draft">Save draft</button><button type="submit" class="button" name="mode" value="publish">Publish to parent</button></div></form></section><div class="stack" style="margin-top:1.4rem">${rs.map(r=>`<section class="panel"><div class="panel-header"><h2>${esc(r.month)}</h2>${tag(r.status,r.status==='Published'?'ready':'draft')}</div><div class="report-content">${esc(r.body)}</div></section>`).join('')}</div>`;}
return `<a class="back-breadcrumb" href="${href('students')}">Back to students</a>${top(s.name,s.programme+' '+s.subject+' · '+s.level,`<div class="button-row"><button class="button secondary" data-action="start-preview" data-role="student" data-student="${s.id}">View as student</button><button class="button secondary" data-action="start-preview" data-role="parent" data-student="${s.id}">View as parent</button></div>`)}${importReviewPanel(s)}<nav class="profile-tabs" aria-label="Student profile sections">${[['overview','Overview'],['arrangements','Arrangements'],['lessons','Lessons'],['messages','Messages'],['reports','Parent reports'],['billing','Billing']].map(([t,label])=>`<a class="${tab===t?'active':''}" href="${href('student','id='+s.id+'&tab='+t)}">${label}</a>`).join('')}</nav>${body}`;}
function accountPage(){if(role()==='admin')return settingsPage();const isParent=role()==='parent',p=isParent?db.parents.find(p=>p.id===me.parentId):currentStudent(),s=currentStudent();return top('Account','Keep your contact information up to date.')+`<section class="panel"><h2>${isParent?'Your contact information':'Your details'}</h2><form id="account-form"><div class="form-fields">${field('Full name','name',p.name,'text','required')}${!isParent?field('Preferred name','preferred',p.preferred):field('Billing name','billingName',p.billingName)}${field('Email address','email',p.email,'email','readonly required')}${isParent?field('Mobile number','mobile',p.mobile):field('Pronouns (optional)','pronouns',p.pronouns)}${field('Country','country',p.country,'text','required')}${field('Time zone','zone',p.zone,'text','required')}${isParent?select('Preferred contact method','contact',['Email','Phone','WhatsApp'],p.contact):''}</div><p class="meta" style="margin-top:.8rem">Time zone: use a location such as America/Toronto or Europe/London.</p><div class="button-row"><button class="button">Save details</button></div></form></section>${isParent?`<section class="panel" style="margin-top:1.4rem"><h2>${esc(s.preferred)}’s contact information</h2><form id="child-account-form" data-student="${s.id}"><div class="form-fields">${field('Student name','name',s.name,'text','required')}${field('Student email','email',s.email,'email','readonly required')}${field('Country','country',s.country)}${field('Time zone','zone',s.zone)}</div><div class="button-row"><button class="button secondary">Save student contact details</button></div></form></section>`:''}<section class="panel" style="margin-top:1.4rem"><h2>Agreed tutoring arrangements</h2><dl class="detail-list"><dt>Course</dt><dd>${esc(s.programme+' '+s.subject+' · '+s.level)}</dd><dt>Regular lesson</dt><dd>${esc(s.day+' · '+s.time)}</dd><dt>Length</dt><dd>${s.length} minutes</dd>${isParent?`<dt>Rate</dt><dd>${money(s.rate,s.currency)} / hour</dd><dt>Discount</dt><dd>${s.discount}%</dd>`:''}</dl><div class="button-row">${button('Ask Amanda about a change',href('messages',isParent?'thread='+me.parentId+'-parent':''),'secondary small-button')}</div></section>`;}
function loginPage(){return `${header()}<main id="main" class="signin-wrap"><div class="signin-copy"><p class="portal-kicker">Auxesis Education</p><h1>Your learning,<br>in one place.</h1><p>Prepare for lessons, follow your progress and keep in touch with Amanda.</p><p class="subtle">Auxesis provides portal access after tutoring is confirmed. Sign in using the email address Amanda has linked to your student or parent record.</p></div><section class="signin-box"><h2>Portal / Sign in</h2><p>For existing students and families.</p><div class="button-row"><button class="button" data-action="google-signin">Sign in with Google</button></div><p class="meta">If you need help accessing your portal, contact Amanda.</p>${loginError?`<div class="notice warning"><p>${esc(loginError)}</p></div>`:''}${button('Enquire about tutoring','/enquire/','secondary small-button')}</section></main>${footer()}`;}
const policyCopy={tutoring:'Payment is required before the agreed tutoring block. Cancellations with seven days or more notice are not charged; with 12 hours to seven days notice, reschedule within four weeks. Less than 12 hours notice or a no-show is chargeable. Tutor cancellations are not charged. Contact Amanda to discuss rescheduling.',technology:'Use your personal Google account for lessons and your assigned portal access. Have a working camera, microphone and reliable internet connection, and a quiet place to study. Planning, lesson records, resources and messages are available in the private Auxesis Portal. Follow the agreed lesson and recording arrangements.',privacy:'Auxesis uses contact, course and learning information, lesson records, messages, attachments and billing information to arrange and deliver tutoring. Portal records are available to Amanda and the permitted student and linked parent or guardian. Google provides sign-in, Cloudflare hosts the website, and Floot provides the portal database and file storage. Contact Amanda about corrections, access or deletion requests. See the full Privacy & Consent Policy.'};
function onboardingPage(){if(role()!=='parent')return shell(learningPage());const o=db.onboarding;if(!o)return shell(unavailable());const step=o.step,labels=['Parent','Student','Learning','Arrangements','Policies'];if(o.complete)return `${controls()}${header()}<main class="wizard-wrap"><section class="panel"><p class="portal-kicker">Onboarding complete</p><h1>You’re ready for your first lesson.</h1><p>Your details and acknowledgements are saved. Your dashboard brings together the next lesson, planning and messages.</p><div class="button-row"><button class="button" data-action="finish-onboarding">Open parent dashboard</button></div></section></main>${footer()}`;
let fields='';if(step===0)fields=`<h2>Parent / guardian information</h2><p>The invitation is linked to ${esc(o.parent.email)}.</p><div class="form-fields">${field('Full name','name',o.parent.name,'text','required')}${field('Email address','email',o.parent.email,'email','readonly required')}${field('Mobile number','mobile',o.parent.mobile,'tel','required')}${field('Country','country',o.parent.country,'text','required')}${field('Time zone','zone',o.parent.zone,'text','required')}${select('Preferred contact method','contact',['Email','Phone','WhatsApp'],o.parent.contact)}${field('Name for invoices','billingName',o.parent.billingName,'text','required')}</div>`;
if(step===1)fields=`<h2>Student information</h2><p>The student uses their own email for their account.</p><div class="form-fields">${field('Full name','name',o.student.name,'text','required')}${field('Preferred name','preferred',o.student.preferred)}${field('Pronouns (optional)','pronouns',o.student.pronouns)}${field('Student email / login','email',o.student.email,'email','readonly required')}${field('Country','country',o.student.country,'text','required')}${field('Time zone','zone',o.student.zone,'text','required')}${field('Current year / level','year',o.student.year,'text','required')}${field('Curriculum / programme','programme',o.student.programme,'text','required')}${field('Subject(s)','subject',o.student.subject,'text','required')}${field('Course level (e.g. HL / SL)','level',o.student.level)}${field('Exam board, where relevant','board',o.student.board)}${field('Expected examination year / date','exam',o.student.exam)}</div>`;
if(step===2)fields=`<h2>The student’s perspective</h2><p>These questions are for the student to answer in their own words.</p><div class="form-fields">${area('What would you most like help with?','help',o.learning.help)}${area('What are you finding most challenging at the moment?','challenge',o.learning.challenge)}${area('What are you hoping to achieve through tutoring?','goals',o.learning.goals)}${area('Any upcoming tests, exams, assignments or important dates?','dates',o.learning.dates)}${area('Anything else that would help Amanda support you effectively?','other',o.learning.other)}</div>`;
if(step===3){const s=currentStudent();fields=`<h2>Confirm your tutoring arrangements</h2><p>Amanda has entered the agreed arrangements. Contact her if anything needs correcting.</p><dl class="detail-list"><dt>Regular lesson</dt><dd>${esc(s.day+' · '+s.time)}</dd><dt>Lesson length</dt><dd>${s.length} minutes</dd><dt>Rate</dt><dd>${money(s.rate,s.currency)} / hour</dd><dt>Discount</dt><dd>${s.discount}%</dd><dt>Package</dt><dd>${balanceValue(s,'remaining')} prepaid lessons remaining</dd><dt>Start date</dt><dd>${s.startDate?shortDate(s.startDate):'Not recorded'}</dd></dl><label class="check-label"><input name="confirm" type="checkbox" required ${o.arrangementsConfirmed?'checked':''}>These arrangements are correct.</label><a class="plain-link" href="${href('messages','thread='+me.parentId+'-parent')}">Message Amanda about a correction</a>`;}
if(step===4)fields=`<h2>Policies & acknowledgements</h2><p>For a student under 18, the parent or guardian completes this step.</p>${[['tutoring','Tutoring & Cancellation Policy','I agree to the Tutoring & Cancellation Policy.'],['technology','Technology & Online Learning Policy','I agree to the Technology & Online Learning Policy.'],['privacy','Privacy Policy','I have read the Privacy Policy.']].map(([id,title,label])=>`<details class="policy-details"><summary>${title}</summary><p>${esc(policyCopy[id])}<br><a href="${id==='privacy'?'/privacy-consent/':'/tutoring-policies/'}" target="_blank" rel="noopener">Read the complete policy</a></p><p class="meta">Version 2026-10-03 · 3 October 2026</p></details><label class="check-label"><input name="${id}" type="checkbox" required ${o.agreements.some(a=>a.policy===id)?'checked':''}>${label}</label>`).join('')}`;
return `${controls()}${header()}<main class="wizard-wrap"><p class="portal-kicker">Family invitation · ${esc(personName())}</p><h1>Welcome to Auxesis.</h1><p>A few short steps to get ready for tutoring.</p><div class="wizard-progress" aria-label="Onboarding progress">${labels.map((l,i)=>`<span class="${i===step?'current':i<step?'done':''}" ${i===step?'aria-current="step"':''}>${i+1}. ${l}</span>`).join('')}</div><section class="panel"><form id="onboarding-form" data-step="${step}">${fields}<div class="button-row" style="justify-content:space-between;margin-top:2rem">${step>0?'<button class="button secondary" type="button" data-action="wizard-back">Back</button>':'<span></span>'}<button class="button" type="submit">${step===4?'Complete onboarding':'Continue'}</button></div></form></section></main>${footer()}`;}
const addMonth=value=>{const d=new Date(value),dayOfMonth=d.getUTCDate();d.setUTCDate(1);d.setUTCMonth(d.getUTCMonth()+1);const last=new Date(Date.UTC(d.getUTCFullYear(),d.getUTCMonth()+1,0)).getUTCDate();d.setUTCDate(Math.min(dayOfMonth,last));return d;};
const entitled=()=>db.entitled;
function libraryPage(){if(!entitled())return `${controls()}${header()}<main class="library-shell"><h1>Resource Library</h1><section class="panel"><h2>Your access period has ended</h2><p>Full access continues throughout tutoring and for one additional month. Contact Amanda to discuss further access.</p>${button('Message Amanda',href('messages'),'secondary')}</section></main>${footer()}`;
const collection=qs().get('collection')||'',subject=qs().get('subject')||'',query=qs().get('q')||'',type=qs().get('type')||'';const items=db.resources.filter(r=>(!collection||r.programme===collection)&&(!subject||r.subject===subject)&&(!type||r.type===type)&&(r.title+' '+r.description+' '+r.category).toLowerCase().includes(query.toLowerCase()));return `${controls()}${header()}<main class="library-shell" id="main"><div class="page-top"><div><p class="portal-kicker">Auxesis Education</p><h1>Resource Library</h1><p>Find a useful guide, practise a skill or revisit an idea.</p></div>${button('Return to portal',href('dashboard'),'secondary')}${role()==='admin'?button('Manage resources','/resources/manage/','secondary'):''}</div><div class="resource-access">${icon('book')}<span>Full access to every collection · During tutoring and one month after</span>${tag('Active','ready')}</div><div class="library-layout"><nav class="library-categories" aria-label="Resource collections"><h2>Collections</h2><a href="/resources/" class="${!collection?'active':''}">All resources</a>${db.categories.map(c=>`<a href="/resources/?collection=${encodeURIComponent(c.name)}" class="${collection===c.name&&!subject?'active':''}">${esc(c.name)}</a>${collection===c.name?`<div class="subject-links">${c.subjects.map(s=>`<a class="${subject===s?'active':''}" href="/resources/?collection=${encodeURIComponent(c.name)}&subject=${encodeURIComponent(s)}">${esc(s)}</a>`).join('')}</div>`:''}`).join('')}</nav><div><form id="resource-search" class="search-row"><input class="search-input" type="search" name="q" placeholder="Search resources" value="${esc(query)}" aria-label="Search resources"><input type="hidden" name="collection" value="${esc(collection)}"><select name="subject" aria-label="Filter by subject"><option value="">All subjects</option>${[...new Set(db.resources.filter(r=>!collection||r.programme===collection).map(r=>r.subject))].map(s=>`<option ${s===subject?'selected':''}>${esc(s)}</option>`).join('')}</select><select name="type" aria-label="Resource type"><option value="">All types</option>${[...new Set(db.resources.map(r=>r.type))].map(t=>`<option ${t===type?'selected':''}>${esc(t)}</option>`).join('')}</select><button class="button secondary">Search</button></form><p class="meta">${items.length} resource${items.length===1?'':'s'}${collection?' · '+esc(collection):''}${subject?' · '+esc(subject):''}</p><div class="resource-grid">${items.map(r=>`<article class="resource-card">${tag(r.programme+' · '+r.subject)}<h2>${esc(r.title)}</h2><p>${esc(r.description)}</p><span class="meta">${esc(r.category)} · ${esc(r.type)}</span>${button('Open resource','/resources/resource/?id='+r.id,'secondary small-button')}</article>`).join('')||'<p class="empty-note">No resources match these filters. Try a different search.</p>'}</div></div></div></main>${footer()}`;}
function resourcePage(){const r=db.resources.find(r=>r.id===qs().get('id'));if(!r||!entitled())return libraryPage();return `${controls()}${header()}<main class="library-shell" id="main"><a class="back-breadcrumb" href="/resources/">Back to Resource Library</a><div class="page-top"><div><p class="portal-kicker">${esc(r.programme+' · '+r.subject)}</p><h1>${esc(r.title)}</h1><p>${esc(r.description)}</p></div>${tag(r.type)}</div><section class="panel"><p class="meta">${esc(r.category+(r.subcategory?' / '+r.subcategory:''))}</p><div class="report-content">${esc(r.body)}</div>${filesHtml(r.files)}<div class="button-row"><button class="button" data-action="download-resource" data-id="${r.id}">Download PDF</button><button class="button secondary" data-action="print">Print</button></div></section></main>${footer()}`;}
function manageResources(){if(role()!=='admin')return shell(unavailable());return shell(top('Manage resources','Add collections and resources as your library grows.')+`<div class="portal-grid equal"><section class="panel"><h2>Add a collection or category</h2><form id="category-form"><div class="form-fields">${resourceClassification()}</div><div class="button-row"><button class="button">Add category</button></div></form><p class="meta" style="margin-top:1rem">Collections can cover any education, life or career area. Add collections when you have resources ready to share.</p></section><section class="panel"><h2>Add a resource</h2><form id="resource-form"><div class="form-fields">${field('Title','title','','text','required full')}${resourceClassification()}${field('Topic category','category')}${field('Subcategory (optional)','subcategory')}${field('Resource type','type')}${field('Short description','description','','text','required')}${area('Resource content','body')}<label class="portal-field full">Attach a file<input type="file" class="attachment-input" name="files"></label></div><div class="button-row"><button class="button">Add resource</button></div></form></section></div>`);}
function unavailable(){return `<section class="panel"><h1>This record isn’t available.</h1><p>Open a record from your dashboard to continue.</p>${button('Return to dashboard',href('dashboard'),'secondary')}</section>`;}
function go(url){const target=new URL(url,location.origin),p=previewParams();if(p.role&&!target.searchParams.has('view')){target.searchParams.set('view',p.role);target.searchParams.set('previewStudent',p.student||'');}history.pushState({},'',target.pathname+target.search);render();window.scrollTo(0,0);}
function toast(text){const t=document.querySelector('.toast');if(!t)return;t.textContent=text;t.hidden=false;setTimeout(()=>t.hidden=true,5000);}
function dialog(title,body,buttons){const d=document.getElementById('action-dialog');d.innerHTML=`<h2>${title}</h2>${body}<div class="button-row">${buttons}<button class="button secondary" data-action="close-dialog">Close</button></div>`;d.showModal();}
function validZone(z){const m=z.match(/^GMT\s*([+-])\s*(\d{1,2})(?::(\d{2}))?$/i);if(m)return Number(m[2])<=14&&Number(m[3]||0)<60;try{new Intl.DateTimeFormat('en',{timeZone:z});return true;}catch{return false;}}
function pdfBytes(lines){const clean=x=>String(x).normalize('NFKD').replace(/[\u0300-\u036f]/g,'').replace(/[^\x20-\x7E]/g,' ').replace(/[()\\]/g,'\\$&');const wrapped=lines.flatMap(x=>{const parts=String(x).split('\n');return parts.flatMap(p=>{const a=[];while(p.length>85){let n=p.lastIndexOf(' ',85);if(n<20)n=85;a.push(p.slice(0,n));p=p.slice(n).trimStart();}a.push(p);return a;});});const pages=[];for(let i=0;i<wrapped.length;i+=42)pages.push(wrapped.slice(i,i+42));const objects=['<< /Type /Catalog /Pages 2 0 R >>','', '<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>'];const kids=[];for(const page of pages){const pageNum=objects.length+1,streamNum=pageNum+1;kids.push(`${pageNum} 0 R`);objects.push(`<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Resources << /Font << /F1 3 0 R >> >> /Contents ${streamNum} 0 R >>`);let stream='0.16 0.13 0.24 rg\nBT /F1 12 Tf 50 785 Td 17 TL\n';page.forEach((l,i)=>stream+=(i?'T*\n':'')+`(${clean(l)}) Tj\n`);stream+='ET';objects.push(`<< /Length ${stream.length} >>\nstream\n${stream}\nendstream`);}objects[1]=`<< /Type /Pages /Kids [${kids.join(' ')}] /Count ${pages.length} >>`;let pdf='%PDF-1.4\n',offsets=[0];objects.forEach((o,i)=>{offsets.push(pdf.length);pdf+=`${i+1} 0 obj\n${o}\nendobj\n`;});const start=pdf.length;pdf+=`xref\n0 ${objects.length+1}\n0000000000 65535 f \n`;offsets.slice(1).forEach(x=>pdf+=String(x).padStart(10,'0')+' 00000 n \n');pdf+=`trailer\n<< /Size ${objects.length+1} /Root 1 0 R >>\nstartxref\n${start}\n%%EOF`;return pdf;}
function download(lines,name){const blob=new Blob([pdfBytes(lines)],{type:'application/pdf'}),u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),2000);toast('PDF downloaded.');}
function invoiceLines(i){const s={...student(i.studentId),rate:i.rate,discount:i.discount,currency:i.currency},p=db.parents.find(p=>p.id===s.parentId);return ['AUXESIS EDUCATION','INVOICE '+i.number,'','',`Bill to: ${p.billingName}`,`Student: ${s.name}`,`Invoice date: ${shortDate(i.date)}    Due: ${shortDate(i.due)}`,`Status: ${i.status}`,`Rate: ${money(s.rate,s.currency)} / hour    Discount: ${s.discount}%`,'','Date | Description | Hours | Amount',...i.dates.map(d=>`${shortDate(d)} | ${s.programme} ${s.subject} tutoring | ${i.hoursPerLesson||1} | ${money(s.rate*(i.hoursPerLesson||1),s.currency)}`),'',`Subtotal: ${money(i.count*(i.hoursPerLesson||1)*s.rate,s.currency)}`,`Discount (${s.discount}%): ${money(i.count*(i.hoursPerLesson||1)*s.rate*s.discount/100,s.currency)}`,...(i.appliedCredit?[`Applied credit: ${money(i.appliedCredit,s.currency)}`]:[]),`Total: ${money(invoiceTotal(i),s.currency)}`,`Received: ${money(i.received,s.currency)}`,`Balance due: ${money(invoiceBalance(i),s.currency)}`,'',`Payment reference: ${s.name} + ${i.number}`,'Payment methods: PayPal / bank transfer / Canadian e-Transfer','Thank you for choosing Auxesis Education.'];}
let loginError='';
async function api(route,value){const pv=previewParams(),headers=value===undefined?{}:{'Content-Type':'application/json'};if(pv.role){headers['x-auxesis-preview-role']=pv.role;headers['x-auxesis-preview-student']=pv.student||'';}const r=await fetch('/api/portal/'+route,{method:value===undefined?'GET':'POST',credentials:'same-origin',headers,body:value===undefined?undefined:JSON.stringify(value)});const data=await r.json();if(!r.ok){if(r.status===401){me=null;db=empty();socket?.close();render();}throw new Error(data.error||'This change could not be saved. Please retry.');}return data;}
function selectOnboarding(){db.onboarding=db.onboardings.find(o=>o.studentId===currentStudent()?.id);}
async function refresh(show=true){const view=db.calendarView,offset=db.calendarOffset;db=await api('state');me=db.me;account=me.id;db.calendarView=view||'Week';db.calendarOffset=offset||0;if(!db.students.some(s=>s.id===activeChild))activeChild=db.students[0]?.id||'';selectOnboarding();if(show)render();}
async function change(action,values={},message='Saved.'){if(db.preview)throw new Error('This is a read-only preview. Return to Amanda’s workspace to make changes.');const result=await api('command',{action,...values,operationId:crypto.randomUUID()});await refresh();toast(message);return result;}
async function readFiles(input,kind,recordId){const selected=[...(input?.files||[])];if(selected.length>3||selected.some(f=>f.size>2097152))throw new Error('Attach up to three files, each 2 MB or smaller.');const ids=[];for(const f of selected){const mime=f.type||({'pdf':'application/pdf','txt':'text/plain','docx':'application/vnd.openxmlformats-officedocument.wordprocessingml.document','pptx':'application/vnd.openxmlformats-officedocument.presentationml.presentation','xlsx':'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'}[f.name.split('.').pop().toLowerCase()]);const upload=await api('upload',{kind,recordId,name:f.name,bytes:f.size,mime});const r=await fetch(upload.presignedUrl,{method:'PUT',headers:upload.headers,body:f});if(!r.ok)throw new Error('The attachment could not be uploaded. Please try again.');ids.push(upload.id);}return ids;}
const paymentOptions=()=>`<div class="button-row">${db.settings.paypal?`<a class="button secondary small-button" href="${esc(db.settings.paypal)}" target="_blank" rel="noopener noreferrer">Pay with PayPal</a>`:''}${db.settings.transfer?`<button class="button secondary small-button" data-action="transfer-details">View transfer details</button>`:''}</div>${!db.settings.paypal&&!db.settings.transfer?'<p class="meta">Amanda will provide payment details for your agreed arrangements.</p>':''}`;
function settingsPage(){return top('Payment details','These details are shown to parents with issued invoices.')+`<section class="panel"><form id="settings-form">${area('Bank transfer / Canadian e-Transfer details','transfer',db.settings.transfer||'')}${field('PayPal payment link','paypal',db.settings.paypal||'','url')}<div class="button-row"><button class="button">Save payment details</button></div></form></section>`;}
function learningPage(){const s=currentStudent();if(!s)return unavailable();const o=db.onboarding;return top('Your learning','Tell Amanda what would help you most.')+`<section class="panel"><form id="student-learning-form">${area('What would you like help with?','help',o?.learning.help||'')}${area('What feels difficult?','challenge',o?.learning.challenge||s.challenge)}${area('What do you hope to achieve?','goals',o?.learning.goals||s.goals)}${area('Upcoming assessments or dates','dates',o?.learning.dates||'')}${area('Anything else Amanda should know?','other',o?.learning.other||'')}<div class="button-row"><button class="button">Save learning priorities</button></div></form></section>`;}
async function onSubmit(event){const f=event.target;if(!f.matches('form'))return;event.preventDefault();if(db.preview&&!['resource-search','student-search'].includes(f.id)){if(f.id==='onboarding-form'){db.onboarding.step=Math.min(4,db.onboarding.step+1);render();return;}return toast('Read-only preview · no changes are saved.');}if(busy||!f.reportValidity())return;const data=Object.fromEntries(new FormData(f).entries()),values=['resource-form','category-form'].includes(f.id)?resourceValues(data):data;busy=true;const submit=f.querySelector('button[type="submit"],button:not([type])');if(submit)submit.disabled=true;try{
if(f.id==='planning-form')await change('planning',{id:f.dataset.lesson,text:values.planning,files:await readFiles(f.elements.files,'lesson',f.dataset.lesson)},'Planning added. Amanda can see your update.');
if(f.id==='notes-form')await change('notes',{id:f.dataset.lesson,covered:values.covered,outcome:values.outcome,next:values.next},'Lesson notes saved.');
if(f.id==='private-notes-form')await change('privateNotes',{id:f.dataset.lesson,text:values.private},'Private note saved.');
if(f.id==='lesson-resource-form')await change('attachResource',{id:f.dataset.lesson,resourceId:values.resource},'Resource attached.');
if(f.id==='message-form')await change('message',{id:f.dataset.thread,text:values.message,files:await readFiles(f.elements.files,'thread',f.dataset.thread)},'Message sent.');
if(f.id==='account-form'||f.id==='child-account-form')await change('profile',{...values,kind:f.id==='account-form'&&role()==='parent'?'parent':'student',id:f.dataset.student||currentStudent()?.id},'Contact details saved.');
if(f.id==='arrangements-form')await change('arrangements',{...values,id:f.dataset.student},'Tutoring arrangements saved.');
if(f.id==='report-form')await change('report',{...values,studentId:f.dataset.student,publish:event.submitter?.value==='publish'},event.submitter?.value==='publish'?'Report published to the parent.':'Private draft saved.');
if(f.id==='category-form')await change('category',values,'Category added.');
if(f.id==='resource-form'){const id=crypto.randomUUID();await change('resource',{...values,id,files:await readFiles(f.elements.files,'resource',id)},'Resource added.');}
if(f.id==='onboarding-form'){const o=db.onboarding;await change('onboarding',{...values,id:o.id,step:Number(f.dataset.step),policyVersion:db.policyVersion,confirm:f.elements.confirm?.checked||false,tutoring:f.elements.tutoring?.checked||false,technology:f.elements.technology?.checked||false,privacy:f.elements.privacy?.checked||false},'Onboarding saved.');}
if(f.id==='student-learning-form')await change('onboarding',{...values,id:db.onboarding.id,step:2},'Learning priorities saved.');
if(f.id==='prepare-invoice-form'){const r=await change('invoice',values,'Invoice draft ready for review.');document.querySelector('dialog[open]')?.close();go(href('invoice','id='+r.invoiceId));}
if(f.id==='payment-form')await change('payment',{...values,id:f.dataset.invoice},'Payment recorded.');
if(f.id==='settings-form')await change('settings',values,'Payment details saved.');
if(f.id==='invite-form'){const r=await change('invite',values,'Family records linked.');go(href('student','id='+r.studentId));dialog('Family access is ready',`<p>Send this invitation to <strong>${esc(values.parentName)}</strong> and <strong>${esc(values.studentName)}</strong> after tutoring is confirmed.</p><p>Sign in with your Google account using the email Amanda has linked to your family record: ${esc(values.parentEmail)} (parent) or ${esc(values.studentEmail)} (student).</p><p><a href="/portal/">https://auxesis-education.pages.dev/portal/</a></p><p class="meta">The family can now complete onboarding. This invitation has not been emailed automatically.</p>`,`<button class="button" data-action="copy-invitation">Copy invitation link</button>`);}
if(f.id==='schedule-form')await change('schedule',{...values,start:localInZone(values.start,values.zone)},'Lessons scheduled.');
if(f.id==='move-form')await change('reschedule',{id:f.dataset.lesson,start:localInZone(values.start,values.zone),hours:values.hours},'Lesson moved.');
if(f.id==='resource-search')go('/resources/?'+new URLSearchParams(Object.entries(values).filter(([,v])=>v)).toString());
if(f.id==='student-search')go(href('students','q='+encodeURIComponent(values.q)));
}catch(e){toast(e.message);}finally{busy=false;if(submit)submit.disabled=false;}}
function localInZone(value,z){if(!validZone(z))throw new Error('Use a location time zone, such as America/Toronto.');const target=new Date(value+'Z').getTime();let utc=target;for(let i=0;i<3;i++){const p=new Intl.DateTimeFormat('en-CA',{timeZone:z,year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hourCycle:'h23'}).formatToParts(new Date(utc));const parts=Object.fromEntries(p.map(x=>[x.type,x.value]));const represented=Date.UTC(+parts.year,+parts.month-1,+parts.day,+parts.hour,+parts.minute,+parts.second);utc+=target-represented;}return new Date(utc).toISOString();}
function scheduleDialog(l){if(!db.students.length)return toast('Invite a family before scheduling lessons.');dialog(l?'Move this lesson':'Schedule lessons',`<form id="${l?'move-form':'schedule-form'}" ${l?'data-lesson="'+l.id+'"':''}><div class="form-fields">${!l?`<label class="portal-field full">Student<select name="studentId">${db.students.map(s=>`<option value="${s.id}">${esc(s.name)}</option>`).join('')}</select></label>`:''}${field('First lesson date and time','start','','datetime-local','required')}${field('Time zone','zone','America/Toronto','text','required')}${!l?field('Number of weekly lessons','count',1,'number','min="1" max="24" required'):''}${field('Hours per lesson','hours',l?.hours||1,'number','min="0.25" max="3" step="0.25" required')}</div><div class="button-row"><button class="button">${l?'Save new time':'Schedule lessons'}</button></div></form>`,'');}
async function onAction(event){const el=event.target.closest('[data-action]');if(!el)return;event.preventDefault();const action=el.dataset.action,id=el.dataset.id;try{
if(action==='start-preview'){socket?.close();socket=null;history.pushState({},'',`/portal/dashboard/?view=${el.dataset.role}&previewStudent=${encodeURIComponent(el.dataset.student)}`);await refresh();return;}
if(action==='exit-preview'){const sid=db.preview?.studentId;history.pushState({},'',sid?'/portal/student/?id='+encodeURIComponent(sid):'/portal/students/');await refresh();connect();return;}
if(action==='preview-onboarding'){go(href('onboarding'));return;}
if(db.preview&&!['close-dialog','download-invoice','download-resource','print','transfer-details','wizard-back','finish-onboarding'].includes(action))return toast('Read-only preview · no changes are saved.');
if(action==='invite-family'&&db.settings.reviewMode)return toast('Family access is disabled while the portal is being reviewed.');
if(action==='google-signin'){el.disabled=true;location.assign('/api/portal/auth/start');}
if(action==='logout'){await api('logout',{});socket?.close();me=null;account='';db=empty();go('/portal/');}
if(action==='close-dialog')document.getElementById('action-dialog').close();
if(action==='transfer-details')dialog('Transfer details',`<p style="white-space:pre-wrap">${esc(db.settings.transfer)}</p><p>Use the student’s name and invoice number as the reference.</p>`,'');
if(action==='copy-invitation'){await navigator.clipboard.writeText('https://auxesis-education.pages.dev/portal/');toast('Invitation link copied.');}
if(action==='invite-family'&&role()==='admin')dialog('Invite a family',`<p>Add access after tutoring has been confirmed. Each person signs in with their assigned Google email.</p><form id="invite-form"><div class="form-fields">${field('Parent / guardian name','parentName','','text','required')}${field('Parent Google email','parentEmail','','email','required')}${field('Student name','studentName','','text','required')}${field('Student Google email','studentEmail','','email','required')}${field('Programme','programme')}${field('Subject','subject')}${field('Agreed hourly rate','rate',0,'number','min="0" step="0.01" required')}${select('Currency','currency',['USD','CAD','GBP','EUR','AUD'],'USD')}</div><div class="button-row"><button class="button">Provide family access</button></div></form>`,'');
if(action==='schedule'&&role()==='admin')scheduleDialog();
if(action==='reschedule'&&role()==='admin')scheduleDialog(db.lessons.find(l=>l.id===id));
if(action==='tutor-cancel'&&role()==='admin'&&confirm('Record a tutor cancellation without charging this lesson?'))await change('tutorCancel',{id},'Tutor cancellation recorded.');
if(action==='cancel-lesson'&&role()==='parent'){const l=db.lessons.find(l=>l.id===id),hours=(new Date(l.start)-new Date())/3600000;dialog('Cancel this lesson?',`<p>${esc(student(l.studentId).name)} · ${esc(fullDate(l.start))} · ${esc(time(l.start))}</p><div class="notice ${hours<12?'warning':''}"><p>${hours<12?'Less than 12 hours’ notice is chargeable. One lesson will be deducted from the prepaid balance.':hours<168?'Between 12 hours and 7 days: contact Amanda to reschedule within four weeks under the agreed policy.':'At least 7 days’ notice: this cancellation is not charged.'}</p></div><p>The lesson stays in the history. Amanda will see the cancellation.</p>`,`<button class="button danger" data-action="confirm-cancel" data-id="${id}">Confirm cancellation</button>`);}
if(action==='confirm-cancel')await change('cancel',{id},'Lesson cancelled. Amanda has been notified in the portal.');
if(action==='no-show'&&confirm('Record a missed lesson and deduct one prepaid lesson?'))await change('noShow',{id},'Missed lesson recorded.');
if(action==='complete-lesson')await change('complete',{id},'Lesson marked completed and balance updated.');
if(action==='mark-read')await change('markRead',{id},'Conversation marked read.');
if(action==='issue-invoice'&&confirm('Issue this invoice to the parent?'))await change('issue',{id},'Invoice issued to the parent.');
if(action==='prepare-invoice'){if(!db.students.length)return toast('Invite a family first.');dialog('Prepare a future invoice',`<form id="prepare-invoice-form"><div class="form-fields"><label class="portal-field full">Student<select name="studentId">${db.students.map(s=>`<option value="${s.id}">${esc(s.name)}</option>`).join('')}</select></label>${field('First lesson date','first',date(14).slice(0,10),'date','required')}${field('Lessons in block','count',4,'number','required min="1" max="24"')}${field('Hours per lesson','hours',1,'number','required min="0.25" max="3" step="0.25"')}${field('Payment due date','due',date(12).slice(0,10),'date','required')}</div><p class="meta">Dates repeat weekly. An existing future draft is opened for review.</p><div class="button-row"><button class="button">Create draft</button></div></form>`,'');}
if(action==='record-payment'){const i=db.invoices.find(i=>i.id===id);dialog('Record a payment',`<form id="payment-form" data-invoice="${id}"><p>${esc(i.number)} · ${esc(i.currency)}</p><div class="form-fields">${field('Amount received','amount',invoiceBalance(i),'number','required min="0.01" step="0.01"')}${field('Date received','date',new Date().toISOString().slice(0,10),'date','required')}${select('Payment method','method',['PayPal','Bank transfer','e-Transfer','Other'],'PayPal')}</div><div class="button-row"><button class="button">Save payment</button></div></form>`,'');}
if(action==='organise-notes'){const f=document.getElementById('notes-form'),raw=f.elements.rawNotes.value.trim(),matches=[...raw.matchAll(/(?:^|\n|\s)(Covered|What we covered|Outcome|Next steps|Next):\s*/gi)];if(matches.length){for(let n=0;n<matches.length;n++){const k=/covered/i.test(matches[n][1])?'covered':/outcome/i.test(matches[n][1])?'outcome':'next';f.elements[k].value=raw.slice(matches[n].index+matches[n][0].length,matches[n+1]?.index||raw.length).trim();}}else f.elements.covered.value=raw;toast('Notes organised for review. Edit the fields, then save.');}
if(action==='draft-report'){const s=student(el.dataset.student),ls=db.lessons.filter(l=>l.studentId===s.id&&l.status==='Completed'&&fmt(l.start,{month:'long',year:'numeric'})===document.getElementById('report-form').elements.month.value);document.getElementById('report-form').elements.body.value=['Learning and topics',...ls.map(l=>shortDate(l.start)+': '+l.notes.covered),'','Progress and areas for development',...ls.map(l=>l.notes.outcome).filter(Boolean),'','Priorities for the coming month',...ls.map(l=>l.notes.next).filter(Boolean)].join('\n');toast('Draft prepared. Review and edit before publishing.');}
if(action==='download-invoice'){const i=visibleInvoices().find(i=>i.id===id);if(i)download(invoiceLines(i),i.number+'.pdf');}
if(action==='download-resource'&&entitled()){const r=db.resources.find(r=>r.id===id);if(r)download(['AUXESIS EDUCATION',r.title,r.programme+' | '+r.subject,'',r.body],r.title.toLowerCase().replace(/[^a-z0-9]+/g,'-')+'.pdf');}
if(action==='print')window.print();
if(action==='calendar-view'){db.calendarView=el.dataset.view;db.calendarOffset=0;render();}
if(action==='calendar-prev'){db.calendarOffset--;render();}
if(action==='calendar-next'){db.calendarOffset++;render();}
if(action==='calendar-today'){db.calendarOffset=0;render();}
if(action==='wizard-back'){db.onboarding.step=Math.max(0,db.onboarding.step-1);render();}
if(action==='finish-onboarding')go(href('dashboard'));
}catch(e){toast(e.message);}}
async function connect(){if(db.preview)return;try{const auth=await api('realtime',{});socket=new WebSocket(auth.wssEndpoint+'?token='+encodeURIComponent(auth.token));socket.onopen=()=>socket.send(JSON.stringify({action:'subscribe',channel:'account:'+me.id}));socket.onmessage=e=>{try{const d=JSON.parse(e.data);if(d.channel&&d.data?.type==='refresh'){if(document.querySelector('form textarea:focus,form input:focus,dialog[open]')){refreshPending=true;toast('New information is available. Save your changes or reopen the page to refresh.');}else refresh().catch(()=>{});}}catch{}};socket.onclose=()=>{if(me)setTimeout(connect,15000);};}catch{}}
async function initialise(){const fragment=new URLSearchParams(location.hash.slice(1));history.replaceState({},'',location.pathname+location.search);if(fragment.get('error'))loginError=fragment.get('error')==='not-invited'?'This email has not been assigned portal access. Contact Amanda.':'Sign-in could not be completed. Please try again.';try{if(fragment.get('signin'))await api('auth/exchange',{token:fragment.get('signin')});await refresh(false);if(location.pathname==='/portal/')history.replaceState({},'',href('dashboard'));render();connect();}catch(e){if(!loginError&&fragment.get('signin'))loginError=e.message;render();}}

function render(){const p=path();if(!role()&&p!=='/portal/'){history.replaceState({},'','/portal/');root.innerHTML=loginPage();return;}const views={'/portal/dashboard/':dashboard,'/portal/lessons/':lessonsPage,'/portal/lesson/':lessonPage,'/portal/messages/':messagesPage,'/portal/reports/':reportsPage,'/portal/billing/':billingPage,'/portal/invoice/':invoicePage,'/portal/calendar/':calendarPage,'/portal/students/':studentsPage,'/portal/student/':studentPage,'/portal/account/':accountPage};if(p==='/portal/')root.innerHTML=role()?shell(dashboard()):loginPage();else if(p==='/portal/onboarding/')root.innerHTML=onboardingPage();else if(p==='/resources/')root.innerHTML=libraryPage();else if(p==='/resources/resource/')root.innerHTML=resourcePage();else if(p==='/resources/manage/')root.innerHTML=manageResources();else root.innerHTML=shell((views[p]||unavailable)());if(role()!=='admin'&&db.onboarding&&!db.onboarding.complete&&p!=='/portal/onboarding/'){const main=document.getElementById('main');if(main)main.insertAdjacentHTML('afterbegin',`<div class="notice"><p>${role()==='parent'?'Complete your family details and policy acknowledgements before tutoring.':'Share your learning goals with Amanda.'} <a href="${href('onboarding')}">Open onboarding</a></p></div>`);}document.title=(document.querySelector('h1')?.textContent||'Portal')+' | Auxesis Education';}
root.addEventListener('click',event=>{onAction(event);if(event.defaultPrevented)return;const a=event.target.closest('a[href]');if(!a||event.button!==0||event.ctrlKey||event.metaKey||a.hasAttribute('download'))return;const u=new URL(a.href);if(u.origin===location.origin&&(u.pathname.startsWith('/portal/')||u.pathname.startsWith('/resources/'))){event.preventDefault();document.querySelector('dialog[open]')?.close();go(u.pathname+u.search);}});
root.addEventListener('submit',onSubmit);
root.addEventListener('change',event=>{if(event.target.id==='child'){activeChild=event.target.value;selectOnboarding();render();}if(event.target.matches('[data-resource-select]'))updateResourceOtherFields(event.target.form);});
window.addEventListener('popstate',()=>refresh().catch(()=>render()));
setInterval(()=>document.querySelectorAll('[data-countdown]').forEach(el=>el.textContent=countdown(el.dataset.countdown)),60000);
initialise();
})();

